uncompiledSrcDoc.css:
.table-wrapper {
  width: 100%;
	overflow: hidden;
	padding: 0;
	margin: 0;

}
.table-root {
  width: max-content;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0; 
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 12px;
	padding: 0;
	margin: 0;
}

.table-root th,
.table-root td {
  border: 0.9px solid #d0d5dd;
  padding: 3px;
  text-align: left;
  vertical-align: top;
  word-break: normal;          
  overflow-wrap: break-word;   
  white-space: normal;
  min-width: 50px;
  line-height: 1.2;
  min-height: 32px;
	box-sizing: border-box;
}
.table-root td {
  vertical-align: middle;
  padding: 0 4px;       
  line-height: 28px;        
  height: 28px;            
  overflow: hidden;
  text-overflow: ellipsis;
  box-sizing: border-box;
}

/*.table-root th[style*="sticky"],
.table-root td[style*="sticky"] {
  outline: 1px solid #d0d5dd;
}*/

.table-header th {
  background-color: #F2F9FF !important;
  font-weight: 500;
	word-break: normal;            
  overflow-wrap: break-word;  
  white-space: normal;
	text-align: center;
  vertical-align: middle;
	padding-top: 14px;
	padding-bottom: 7px;
}

/* Не редактируемые строки */
.table-root tr.table-row--readonly td {
  background-color: #f2f4f7 !important;
  font-weight: 500;
  color: #000;
	text-align: center;
  vertical-align: middle;
	line-height: 1.5;
}

/* Не редактируемые колонки */
.table-root th.table-col--readonly,
.table-root td.table-col--readonly {
  background-color: #f2f4f7;
  font-weight: 600;
  color: #000;
	word-break: keep-all;          
  overflow-wrap: break-word;  
  white-space: normal;
	text-align: center;
  vertical-align: middle;
	line-height: 1.5;
}

.table-input:focus {
  border-color: #4f8cff;
  box-shadow: 0 0 0 1px #4f8cff;
}

// Ячейка с выпадающим списком (режим просмотра)
.table-dropdown-cell {
  position: relative;
  cursor: pointer;
  background-color: #fff;
}

// Стрелка  в правой части ячейки 
.table-dropdown-cell::after {
  content: "▼";
  position: absolute;
  right: 6px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 8px;
  color: #999;
  pointer-events: none;
}

.table-root th.table-col--readonly,
.table-root td.table-col--readonly {
  word-break: normal;              
  overflow-wrap: break-word;
  white-space: normal;
}

