  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();

  const firstDayOfMonth = new Date(year, month, 1).getDay();
	const offset = (firstDayOfMonth + 6) % 7; // смещение для начала недели с понедельника
	const daysInMonth = new Date(year, month + 1, 0).getDate();
	const daysInPrevMonth = new Date(year, month, 0).getDate();

	const days = [];
	for (let i = 0; i < offset; i++) {
		days.push({ day: daysInPrevMonth - offset + 1 + i, currentMonth: false });
	}
	for (let i = 1; i <= daysInMonth; i++) {
		days.push({ day: i, currentMonth: true });
	}
	while (days.length < 42) {
		const nextDay = days.length - daysInMonth - offset + 1;
		days.push({ day: nextDay, currentMonth: false });
	}

  const handleDayClick = (day, currentMonth) => {
    let d;
    if (currentMonth) {
