  } else {
    if (targetRect.top - 10 < 0) top = gap;
    else top = targetRect.top - actualHeight - gap;
  }
  if (top < 0) top = gap;
  if (top + actualHeight > viewportHeight) {
    top = viewportHeight - actualHeight - gap;
  }

  const style = {
    position: 'fixed',
    left: targetRect.left,
    top: top,
    width: menuWidth,
    background: 'white',
    border: '1px solid #d0d5dd',
    borderRadius: '4px',
    boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
    zIndex: 1000,
    padding: '6px',
    fontFamily: 'system-ui, -apple-system, sans-serif',
    fontSize: '11px',
  };

  const weekdays = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

  return reactDom.createPortal(
    <div ref={menuRef} style={style}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '4px' }}>
        <button onClick={() => changeMonth(-1)} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '14px', padding: '2px 6px' }}>◀</button>
        <span style={{ fontWeight: 'bold', fontSize: '12px' }}>{`${String(month + 1).padStart(2, '0')}.${year}`}</span>
        <button onClick={() => changeMonth(1)} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '14px', padding: '2px 6px' }}>▶</button>
