      </div>
    </div>,
    document.getElementById('portal')
  );
}

// кастомный dropdown (выпадающий список)
function DropdownMenu ({options, value, onSelect, onClose, targetRect}) {
	const menuRef = React.useRef(null);
	const [menuHeight, setMenuHeight] = React.useState(0);
	const maxHeight = 200;

	// измерение реальной высоты меню выпадающего списка
	React.useLayoutEffect(() => {
		if (menuRef.current) {
			setMenuHeight(menuRef.current.scrollHeight);
		}
	}, [options]);

	// эффект зактрытия при нажатии вне dropdown
	React.useEffect(() => {
		const handleClickOutside = (e) => {
			if (menuRef.current && !menuRef.current.contains(e.target)) {
				onClose();
			}
		};
		document.addEventListener('mousedown', handleClickOutside);
		return () => document.removeEventListener('mousedown', handleClickOutside)
	}, [onClose]);

	if (!targetRect) return null

	const gap = 4;
	const menuWidth = targetRect.width;
	const actualHeight = Math.min(menuHeight || maxHeight, maxHeight);

	const viewportHeight = window.innerHeight;
	// Пытаемся открыть снизу
	const fitsBelow = targetRect.bottom + actualHeight + gap <= viewportHeight;
	// Пытаемся открыть сверху
	const fitsAbove = targetRect.top - actualHeight - gap >= 0;

	let top;
	if (fitsBelow) {
		top = targetRect.bottom + gap;
	} else if (fitsAbove) {
		top = targetRect.top - actualHeight - gap;
	} else {
		 // Не помещается ни сверху, ни снизу – прижимаем к верху или низу
		if (targetRect.top - 10 < 0) {
			top = gap; // слишком мало места сверху
		} else {
			top = targetRect.top - actualHeight - gap;
		}
	}

	// Дополнительная корректировка, чтобы точно не вылезти за пределы
	if (top < 0) top = gap;
	if (top + actualHeight > viewportHeight) {
		top = viewportHeight - actualHeight - gap;
	}

	 const style = {
    position: 'fixed',
    left: targetRect.left,
    top: top,
    width: menuWidth,
    maxHeight: maxHeight,
    overflowY: 'auto',
    background: 'white',
    border: '1px solid #d0d5dd',
    borderRadius: '4px',
    boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
    zIndex: 1000,
    padding: '2px 0',
		fontFamily: 'system-ui, -apple-system, sans-serif',
  };

	return reactDom.createPortal(
		<div ref={menuRef} style={style}>
			{options.map(opt => (
			 <div
			 	key={opt.value}
				style={{
            padding: '4px 12px',
						cursor: 'pointer',
						backgroundColor: opt.value === value ? '#e9edf2' : 'transparent',
						fontSize: '12px',
						fontFamily: 'system-ui, -apple-system, sans-serif',
						color: '#1c1c1c',
						transition: 'background-color 0.15s',
						whiteSpace: 'normal',      
						wordBreak: 'break-word',    
						overflowWrap: 'break-word', 
						maxWidth: '100%',    
          }}
				onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f0f4f9'}
        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = opt.value === value ? '#e9edf2' : 'transparent'}
        onMouseDown={(e) => {
          e.preventDefault(); // предотвращаем потерю фокуса
          onSelect(opt.value);
        }}
			 >
				 {opt.label}
			 </div>
			 ))}
		</div>,
		document.getElementById('portal')
	)
}

//тултип с подсказкой для ввода
function TooltipPortal({ targetRect, message, showBelow, type = 'error' }) {
  const [tooltipWidth, setTooltipWidth] = React.useState(0);
  const tooltipRef = React.useRef(null);
  const maxWidth = 250;

  React.useLayoutEffect(() => {
    if (tooltipRef.current) {
      setTooltipWidth(tooltipRef.current.offsetWidth);
    }
  }, [message]);

  if (!targetRect) return null;

  const tooltipHeight = 36;
  const gap = 4;
  const isInfo = type === 'info';

  const top = showBelow
    ? targetRect.bottom + gap
    : targetRect.top - tooltipHeight - gap;

  // Адаптивная горизонтальная позиция
  let left = targetRect.left;
  const actualWidth = tooltipWidth || maxWidth;
  const rightAligned = targetRect.right + gap;
  const leftAligned = targetRect.left - actualWidth - gap;

  if (rightAligned + actualWidth <= window.innerWidth - 4) {
    left = rightAligned;
  } else if (leftAligned >= 4) {
    left = leftAligned;
  } else {
    left = 4;
  }

  const style = {
    position: 'fixed',
    left: `${left}px`,
    top: `${top}px`,
    background: isInfo ? '#f0f7ff' : 'white',
    border: `1px solid ${isInfo ? '#4f8cff' : '#ccc'}`,
    padding: '6px 10px',
    borderRadius: '6px',
    boxShadow: '0 2px 6px rgba(0,0,0,0.15)',
    fontSize: '12px',
    color: isInfo ? '#1c3d5a' : '#d32f2f',
    zIndex: 1000,
    pointerEvents: 'none',
    maxWidth: `${maxWidth}px`,
    whiteSpace: 'nowrap',
  };

  return reactDom.createPortal(
    <div ref={tooltipRef} style={style}>{message}</div>,
    document.getElementById('portal')
  );
}

// функция форматирования даты для коррекнтого отображения
function formatDate (value) {
	if (!value) return '';

	const isoMatch = String(value).match(/^(\d{4})-(\d{2})-(\d{2})/);
	if (isoMatch) {
		return `${isoMatch[3]}.${isoMatch[2]}.${isoMatch[1]}`;
	}
	return value
}

// специальный парсердля для индексов колонок и строк (необходимо, чтобы можно было воспринимать и перечисления через запятую и указание диапазаона через тире, и спользуеся в особых ячейках с подсчетом сумм для них)
function parseIndexList(str) {
  if (!str) return [];
  const parts = str.split(',').map(s => s.trim()).filter(Boolean);
  const indices = [];
  parts.forEach(part => {
    const range = part.split('-').map(Number);
    if (range.length === 2 && !isNaN(range[0]) && !isNaN(range[1])) {
      const [from, to] = range;
      const start = Math.min(from, to);
      const end = Math.max(from, to);
      for (let i = start; i <= end; i++) indices.push(i);
    } else {
      const single = Number(part);
      if (!isNaN(single)) indices.push(single);
    }
  });
  return indices;
}

//рассчёт ширины колонок
const HEADER_FONT = "500 12px system-ui, -apple-system, sans-serif";
const MIN_WIDTH = 60;
const MAX_AUTO_WIDTH = 420;
const HEADER_PADDING = 1;
const ICON_SPACE = 16;
const AVG_CHAR_WIDTH = 6;

function calculateNaturalWidths(columns) {
  return columns.map(col => {
    // Фиксированная ширина из БД
    if (col.column_width != null && Number(col.column_width) > 0) {
      return Number(col.column_width);
    }

    const text = col.column_print_name || '';
    const len = text.length;

    let charsPerLine;
		if (len <= 10){
			charsPerLine = 5;
		}else if (len <= 15) {
      charsPerLine = 12;
    } else if (len <= 30) {
      charsPerLine = 15;
    } else if (len <= 60) {
      charsPerLine = 17;
    } else {
      charsPerLine = 25;
    }

    let width = charsPerLine * AVG_CHAR_WIDTH + HEADER_PADDING;
    if (col.error_msg) width += ICON_SPACE;

    width = Math.max(width, MIN_WIDTH);
    width = Math.min(width, MAX_AUTO_WIDTH);

    return Math.round(width);
  });
}

