	},[]);


	// ДАЛЕЕ МЕМОИЗАЦИЯ ДАННЫХ useMemo

	// права на реадтикрование
	const hasEditPermission = React.useMemo(() => {
		return (userPermissions || '').includes('report_edit');
	},[userPermissions]);

	// определение видимости, заморозки, колонок и строк, выпадающего списка
	const {
		visibleColumns,
		frozenColumnsCount,
		frozenRowsCount,
		dropdownConfig,
		columnList
	} = React.useMemo(() => {

		// 1) видимые и отсортированные колонки 
		let visible = (columnMetadata || []).filter(col => col.column_is_visible);
		visible.sort((a,b) => a.column_order - b.column_order);

		// 2) количесвто нередактируемых замороженных колонок
		const frozenColsCount = visible.filter(col => !col.column_is_editable).length

		// 3) количесвто нередактируемых замороженных строк
		const frozenRows = (data || []).filter(row => !row.is_editable).length

		// 4) список системных имён колонок
		const columnsList = visible.map(col => `column${col.column_order}`);

		// 5) выпадающие списки
		const dropdownConf = {};

		visible.forEach(col => {
			const fieldName = `column${col.column_order}`;

			if(col.column_data_type.startsWith('dropdown')) {
				try {
					const options = JSON.parse(col.metadata_description);
					if (Array.isArray(options)) {
						dropdownConf[fieldName] = options;
					}
				} catch {
					console.log('ошибка парсинга dropdown', fieldName)
				}
			}
		});		

		return {
			visibleColumns: visible,
			frozenColumnsCount: frozenColsCount,
			frozenRowsCount: frozenRows,
			dropdownConfig: dropdownConf,
			columnList: visible.map(col => `column${col.column_order}`),
		}
	}, [columnMetadata, data]);


	// ЛОГИКА ДЛЯ ПОСТРОЕНИЯ МНОУГОУРОВНЕВОЙ ШАПКИ ТАБЛИЦЫ
	// получение многоуровневых названий 

	const allHeaderRows = React.useMemo(() => {
		if (!visibleColumns || visibleColumns.length === 0) return [];

		const paths = visibleColumns.map(col => {
			let path = col.column_group;
			if (typeof path === 'string') {
				path = path.split('/').filter(Boolean);
			} else if (!Array.isArray(path)) {
				path = [];
			}
			return path;
		});

		const depths = paths.map(p => p.length);
		const maxDepth = Math.max(0, ...depths);
		const totalRows = maxDepth + 1;

		const grid = Array.from({ length: totalRows }, () =>
			Array(visibleColumns.length).fill(null)
		);

		for (let colIndex = 0; colIndex < visibleColumns.length; colIndex++) {
			const col = visibleColumns[colIndex];
			const depth = depths[colIndex];
			const path = paths[colIndex];

			if (depth === 0) {
				// Нет групп – на первом уровне ставим название колонки с rowspan = totalRows
				grid[0][colIndex] = {
					isColumn: true,
					column: col,
					rowspan: totalRows,
				};
				// остальные уровни null
			} else {
				// Есть группы
				for (let level = 0; level < depth; level++) {
					grid[level][colIndex] = {
						isGroup: true,
						name: path[level],
						rowspan: 1,
					};
				}
				// На последнем уровне ставим название колонки (rowspan = 1)
				grid[totalRows - 1][colIndex] = {
					isColumn: true,
					column: col,
					rowspan: 1,
				};
				// Устанавливаем rowspan для последней группы, чтобы она растянулась до нижней строки
				const lastGroupLevel = depth - 1;
				grid[lastGroupLevel][colIndex].rowspan = maxDepth - depth + 1;
			}
		}

		// Группировка по горизонтали
		const rows = [];
		for (let level = 0; level < totalRows; level++) {
			const row = [];
			let currentGroup = null;
			let currentColspan = 0;
			let currentRowspan = 1;

			for (let colIndex = 0; colIndex < visibleColumns.length; colIndex++) {
				const cell = grid[level][colIndex];
				if (!cell) {
					if (currentGroup) {
						row.push({
							...currentGroup,
							colspan: currentColspan,
							rowspan: currentRowspan,
						});
						currentGroup = null;
						currentColspan = 0;
						currentRowspan = 1;
					}
					continue;
				}

				if (cell.isColumn) {
					if (currentGroup) {
						row.push({
							...currentGroup,
							colspan: currentColspan,
							rowspan: currentRowspan,
						});
						currentGroup = null;
						currentColspan = 0;
						currentRowspan = 1;
					}
					row.push({
						isColumn: true,
						column: cell.column,
						colspan: 1,
						rowspan: cell.rowspan || 1,
					});
					continue;
				}

				// Группа
				const key = cell.name;
				if (currentGroup && currentGroup.name === key) {
					currentColspan++;
					currentRowspan = Math.max(currentRowspan, cell.rowspan);
				} else {
					if (currentGroup) {
						row.push({
							...currentGroup,
							colspan: currentColspan,
							rowspan: currentRowspan,
						});
					}
					currentGroup = { name: key, isGroup: true };
					currentColspan = 1;
					currentRowspan = cell.rowspan || 1;
				}
			}
			if (currentGroup) {
				row.push({
					...currentGroup,
					colspan: currentColspan,
					rowspan: currentRowspan,
				});
			}
			rows.push(row);
		}

		return rows;
	}, [visibleColumns]);

		// добавление span 
		const { rowSpans, colSpans } = React.useMemo(() => {
			const rows = [];
			const cols = [];
			(spanMass || []).forEach(span => {
				if (span.type === 'row') {
					rows.push({
						row: span.order,
						start: span.interval_start,
						end: span.interval_end,
					});
				} else if (span.type === 'column') {
					cols.push({
						col: span.order,
						start: span.interval_start,
						end: span.interval_end,
					})
				}
			});
			return { rowSpans: rows, colSpans: cols }
		}, [spanMass])

		// обработчки для получения дополнительных метаданных для особых ячеек 
		const getCellMeta = React.useCallback((rowIndex, colIndex) => {
			const baseColMeta = visibleColumns[colIndex];
			if (!baseColMeta) return null;
			const key = `${rowIndex}-${colIndex}`;
			const override = cellOverrides[key];
			return override ? { ...baseColMeta, ...override } : baseColMeta;
		}, [visibleColumns, cellOverrides]);

	// для рассчёта ширины
	const naturalWidths = React.useMemo(
		() => calculateNaturalWidths(visibleColumns),
		[visibleColumns]
	);

	const finalWidths = React.useMemo(() => {
		const totalNatural = naturalWidths.reduce((sum, w) => sum + w, 0);
		if (containerWidth <= 0 || totalNatural >= containerWidth) {
			return naturalWidths; // скролл, ничего не делаем
		}

		const extra = containerWidth - totalNatural;

		// Делим колонки на фиксированные (из column_width) и автоматические
		const autoIndices = [];
		let totalAuto = 0;
		naturalWidths.forEach((w, i) => {
			const col = visibleColumns[i];
			if (col.column_width != null && Number(col.column_width) > 0) {
				// фиксированная
			} else {
				autoIndices.push(i);
				totalAuto += w;
			}
		});

		if (autoIndices.length === 0) {
			// Все колонки фиксированы – равномерно добавим лишнее (компромисс)
			return naturalWidths.map(w => w + extra / naturalWidths.length);
		} else {
			// Пропорционально увеличиваем только автоматические
			const newWidths = [...naturalWidths];
			autoIndices.forEach(i => {
				newWidths[i] = newWidths[i] + extra * (newWidths[i] / totalAuto);
			});
			return newWidths;
		}
	}, [naturalWidths, containerWidth, visibleColumns]);

	// расчёт смещение для нередактируемых колонок 
	const stickyColOffsets = React.useMemo(() => {
		let offset = 0;
		return visibleColumns.map((col, i) => {
			if (!col.column_is_editable) {
				const currentOffset = offset;
				offset += finalWidths[i] || 100;
				return currentOffset;
			}
			return undefined;
		});
	}, [visibleColumns, finalWidths, containerWidth]);

		// обработчик, который возвращает руглярное выражение, максимальную длину вводимого значения
	const getColumnValidation = React.useCallback((colMeta) => {
		if (!colMeta) return {regex: null, maxLength: Infinity};

		let regex = null;
		if (colMeta.column_regexp && colMeta.column_regexp!=='.*') {
			try {
				regex = new RegExp(colMeta.column_regexp);
			}
			catch (e) {
				console.log('ошибка regexp', colMeta.column_print_name);
			}
		}
		return {
			regex,
			maxLength: colMeta.max_length || Infinity
		}
	}, []);

	// обработчика действия сохранения значения при нажатии enter и его удаления при нажатии esc
	const handleInputKeyDown = (e) => {
		if (e.key === 'Enter') {
			commitEdit(e.target.value);
		} else if (e.key === 'Escape') {
			setEditingCell(null);
			setLocalEditValue('');
			setDropdownTarget(null);
		}
	}

	// обрабочтик клика на ячейку
	const onCellActivate = React.useCallback((rowId, columnName) => {
		const row = data.find(r => r.row_id === rowId);
		if (!row) return;

		// Находим индексы строки и колонки
		const rowIndex = data.findIndex(r => r.row_id === rowId);
		const colIndex = visibleColumns.findIndex(col => `column${col.column_order}` === columnName);
		if (rowIndex === -1 || colIndex === -1) return;

		// Получаем переопределённые метаданные для этой ячейки
		const effectiveCol = getCellMeta(rowIndex, colIndex);
		if (!effectiveCol) return;

		let currentValue = row[columnName] ?? '';

		// Проверяем переопределённый тип, а не оригинальный
		if (effectiveCol.column_data_type?.startsWith('datepicker') && currentValue) {
			const d = new Date(currentValue);
			if (!isNaN(d.getTime())) {
				currentValue = d.toISOString().split('T')[0];
			}
		}

		setEditingCell({ rowId, columnName });
		setLocalEditValue(currentValue);
		setValidationErrors({});
	}, [data, visibleColumns, getCellMeta]);

	// обработчик изменения данных таблицы и передача их в модель
	const commitEdit = React.useCallback((newValueOverride) => {
		if (!editingCell) return;
		const { rowId, columnName } = editingCell; 
		const newValue = newValueOverride !== undefined ? newValueOverride : localEditValue;
		const colMeta = visibleColumns.find(col => 
			`column${col.column_order}` === editingCell.columnName
		);

		const { maxLength } = getColumnValidation(colMeta);
		// Для dropdown пропускаем проверку длины, т.к. значения из списка уже валидны
		const isDropdownType = colMeta?.column_data_type?.startsWith('dropdown');
		if (!isDropdownType && newValue.length > maxLength) {
			setValidationErrors (prev => ({
				...prev, [`${rowId}_${columnName}`]: `Максимальная длина ${maxLength}`,
			}));
			return;
		}

		// Обновляем данные и сбрасываем ошибку
		const newData = data.map(row =>
			row.row_id === rowId ? { ...row, [columnName]: newValue } : row
		);

		const updatedRow = newData.find(r => r.row_id === rowId);
		const rowIndex = data.findIndex(r => r.row_id === rowId);

		setData(newData);
		appsmith.updateModel({
			data: newData, 
			editedCell: {
				column: columnName,
				value: newValue,
				row_id: rowId,
			},
			selectedRow: updatedRow,
			editedRowId: rowId,
			selectedRowId: rowId,
		});

		appsmith.triggerEvent('onCellEdit', {
			column: columnName,
			rowIndex: rowIndex,
			value: newValue,
			row_id: rowId,
			selectedRow: updatedRow,
		});

		setDropdownTarget(null);
		setEditingCell(null);
  	setLocalEditValue('');
		setValidationErrors(prev => {
			const { [`${rowId}_${columnName}`]: _, ...rest } = prev;
			return rest;
		});
		console.log(`${appsmith.model.data} данные изменились`)
	}, [editingCell, localEditValue, data, visibleColumns, getColumnValidation])

	// обработчик редактирования ячейки
	const handleEditorChange = (e) => {
		const newValue = e.target.value;
		if (!editingCell) return;

		const colMeta = visibleColumns.find(col => 
			`column${col.column_order}` === editingCell.columnName
		);

		const {regex, maxLength} = getColumnValidation(colMeta);

		// проверка макимальной длины
		if (newValue.length > maxLength) {
			setValidationErrors(prev => ({
				...prev,
				[`${editingCell.rowId}_${editingCell.columnName}`]: `Максимальная длина ${maxLength}`,
			}));
			return;
		}

		// проверка регулярного выражения
		if (regex && newValue !== '' && !regex.test(newValue)) {
			setValidationErrors(prev => ({
				...prev,
				[`${editingCell.rowId}_${editingCell.columnName}`]: colMeta?.error_msg || 'Некорректное значение',
			}))
			return;
		}
		setValidationErrors(prev => {
			const { [`${editingCell.rowId}_${editingCell.columnName}`]: _, ...rest } = prev;
			return rest;
		});
		setLocalEditValue(newValue)
	};

	// добавление новой строки 
	const handleAddRow = React.useCallback(() => {
		if (!canAddRow) return

		const maxCol = visibleColumns.length > 0 
			? Math.max(...visibleColumns.map(c => c.column_order))
			: 22;

		setData(prevData => {

			const newRow = {
				row_id: data.length + 1,
				is_editable: true,
				is_visible: true,
				row_background_color: null,
				row_text_color: null,
				span_row: null,
				span_from: null,
				row_order_id: data.length + 1,
				is_user_added: true,
			};

			for (let i = 1; i <= maxCol; i++) {
				newRow[`column${i}`] = '';
			}

			const newData = [...prevData, newRow];

			appsmith.updateModel({ data: newData });
			appsmith.triggerEvent('onRowAdded', {
				row: newRow,
				rowIndex: prevData.length,
			});

			console.log('Новая строка добавлена:', newRow);
			console.log('Новый data:', JSON.stringify(newData, null, 2));

			return newData;
		})

		console.log('После updateModel, data в модели:', JSON.stringify(appsmith.model.data, null, 2));

	}, [canAddRow, visibleColumns]);


	//эффект для прокрутки экрана к drordown и datapicker
	React.useEffect(() => {
		if (!editingCell) {
			setDropdownTarget(null);
			setDatePickerTarget(null);
			return;
		}

		const { rowId, columnName } = editingCell;
		const td = document.querySelector(`td[data-rowid="${rowId}"][data-col="${columnName}"]`);
		if (td) {
			// Получаем переопределённые метаданные
			const rowIndex = data.findIndex(r => r.row_id === rowId);
			const colIndex = visibleColumns.findIndex(col => `column${col.column_order}` === columnName);
			if (rowIndex !== -1 && colIndex !== -1) {
				const effectiveCol = getCellMeta(rowIndex, colIndex);
				if (effectiveCol) {
					const rect = td.getBoundingClientRect();
					if (effectiveCol.column_data_type?.startsWith('dropdown')) {
						setDropdownTarget({ rect, columnName, rowId });
						setDatePickerTarget(null);
					} else if (effectiveCol.column_data_type?.startsWith('datepicker')) {
						setDatePickerTarget({ rect, columnName, rowId });
						setDropdownTarget(null);
					} else {
						setDropdownTarget(null);
						setDatePickerTarget(null);
					}
				}
			}
		} else {
			setDropdownTarget(null);
			setDatePickerTarget(null);
		}
	}, [editingCell, visibleColumns, data, getCellMeta]);

	// элмет заголовка колонки
	const renderColumnHeader = (col, index, isSticky = false, rowspan = 1) => {
		const isStickyCol = stickyColOffsets[index] !== undefined;
		const stickyProps = isSticky && isStickyCol
			? { position: 'sticky', left: `${stickyColOffsets[index]}px`, zIndex: 2 }
			: {};

		// Определяем фон явно, учитывая тип колонки
		let headerBg = col.column_background_color;
		if (!headerBg) {
			headerBg = col.column_is_editable ? '#F2F9FF' : '#f2f4f7';
		}

			return (
				<th
					key={col.column_order}
					rowSpan={rowspan}
					className={!col.column_is_editable ? 'table-col--readonly' : ''}
					 style={{
							width: `${finalWidths[index]}px`,
							minWidth: `${finalWidths[index]}px`,
							maxWidth: `${finalWidths[index]}px`,
							backgroundColor: col.column_background_color || '#F2F9FF',
							color: col.column_text_color || undefined,
							position: 'sticky',     // всегда sticky
							top: 0,                 // прилипаем к верху контейнера
							left: isStickyCol ? `${stickyColOffsets[index]}px` : undefined,
							zIndex: isStickyCol ? 4 : 3,  // выше при горизонтальной фиксации
							// ...остальные стили
						}}
				>
					{col.column_print_name}
					{col.error_msg && col.error_msg.trim() !== '' && (
						<span
							style={{
								position: 'absolute',
								top: '0px',
								right: '-2px',
								fontSize: '11px',
								color: '#4f8cff',
								lineHeight: 1,
								padding: '2px 4px',
								pointerEvents: 'auto',
								cursor: 'help',
							}}
							onMouseEnter={(e) =>
								setHoveredHeader({
									targetRect: e.currentTarget.getBoundingClientRect(),
									message: col.error_msg,
								})
							}
							onMouseLeave={() => setHoveredHeader(null)}
						>
							ⓘ
						</span>
					)}
				</th>
			);
		};

	const getColumnIndex = (col) => visibleColumns.findIndex(c => c.column_order === col.column_order);

	const handleDeleteRow = React.useCallback((rowId) => {
		if (!canDeleteRow || !hasEditPermission) return;

		const rowIndex = data.findIndex(r => r.row_id === rowId);
		if (rowIndex === -1) return;

		const newData = data.filter((_, idx) => idx !== rowIndex);
		setData(newData);
		appsmith.updateModel({ data: newData });

		appsmith.triggerEvent('onRowDelete', {
			rowId: rowId,
			rowIndex: rowIndex,
		});
	}, [data, canDeleteRow, hasEditPermission]);


const getStickyStyle = (colIdx, isStickyRow) => {
  const hasColSticky = stickyColOffsets[colIdx] !== undefined;
  if (!hasColSticky && !isStickyRow) return {};
  return {
    position: 'sticky',
    left: hasColSticky ? `${stickyColOffsets[colIdx]}px` : undefined,
    top: isStickyRow ? `${headerHeight}px` : undefined,
    zIndex: isStickyRow ? 2 : 1,
    backgroundColor: isStickyRow ? '#f2f4f7' : undefined,
  };
};

// Функция отрисовки содержимого ячейки
const renderCellContent = ({
  effectiveCol,
  cellValue,
  isEditable,
  isEditingCell,
  isComputed,
  computedValue,
  columnName,
  colIndex,
  rowId,
  isUserAdded,
  isReadonlyRow,
}) => {
  const isDropdown = effectiveCol.column_data_type?.startsWith('dropdown');
  const isDatepicker = effectiveCol.column_data_type?.startsWith('datepicker');

  // Вычисляем displayValue
  let displayValue = cellValue;
  if (isComputed) {
    displayValue = computedValue;
  } else if (isDatepicker) {
    displayValue = formatDate(cellValue) || '\u00A0';
  } else if (isDropdown) {
    const options = dropdownConfig[columnName] || [];
    const option = options.find(opt => opt.value === cellValue);
    displayValue = option ? option.label : (cellValue || '\u00A0');
  }

  // Режим редактирования
  if (isEditingCell) {
    if (isDropdown) {
      return (
        <div style={{ width: '100%', cursor: 'default', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ whiteSpace: 'normal', wordBreak: 'break-word', textOverflow: 'ellipsis', flex: 1 }}>
            {localEditValue || '\u00A0'}
          </span>
          <span style={{ color: '#888', flexShrink: 0, marginLeft: '4px' }}>▼</span>
        </div>
      );
    }
    if (isDatepicker) {
      return (
        <div style={{ width: '100%', cursor: 'default', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span>{localEditValue ? formatDate(localEditValue) : '\u00A0'}</span>
        </div>
      );
    }
    return (
      <input
        autoFocus
        ref={el => { if (el && editingCell && editingCell.inputElement !== el) setEditingCell(prev => prev ? { ...prev, inputElement: el } : null); }}
        value={localEditValue}
        onChange={handleEditorChange}
        onKeyDown={handleInputKeyDown}
        style={{
          width: '100%',
          height: '100%',
          boxSizing: 'border-box',
          border: 'none',
          outline: 'none',
          padding: 0,
          margin: 0,
          background: 'transparent',
          font: 'inherit',
          color: 'inherit',
        }}
      />
    );
  }

  // Режим просмотра
  const isLastColumn = colIndex === visibleColumns.length - 1;
  const canDelete = isUserAdded && canDeleteRow && hasEditPermission;

  // Если dropdown в последней колонке – показываем стрелку и крестик
  if (isDropdown && isEditable && isLastColumn && dropdownConfig[columnName]) {
    return (
      <div style={{ display: 'flex', alignItems: 'center', width: '100%' }}>
        <span style={{ flex: 1, wordBreak: 'break-word', lineHeight: '1.2' }}>{displayValue}</span>
        <span style={{ color: '#888', marginLeft: '4px', flexShrink: 0, fontSize: '8px' }}>▼</span>
        {canDelete && (
          <span
            onClick={(e) => { e.stopPropagation(); handleDeleteRow(rowId); }}
            style={{ fontSize: '14px', color: '#d32f2f', cursor: 'pointer', userSelect: 'none', marginLeft: '8px', flexShrink: 0 }}
          >✕</span>
        )}
      </div>
    );
  }

  // Обычный вывод (включая dropdown не в последней колонке)
  return (
    <div
      className={(dropdownConfig[columnName] && isEditable && isDropdown) ? 'table-dropdown-cell' : ''}
      style={{
        width: '100%',
        position: 'relative',
        ...(isDropdown && isEditable && isLastColumn ? { paddingRight: '26px', boxSizing: 'border-box' } : {}),
      }}
    >
      <span style={{ wordBreak: 'break-word', lineHeight: '1.2', display: 'block' }}>{displayValue}</span>
      {isLastColumn && canDelete && (
        <span
          onClick={(e) => { e.stopPropagation(); handleDeleteRow(rowId); }}
          style={{
            fontSize: '14px',
            color: '#d32f2f',
            cursor: 'pointer',
            userSelect: 'none',
            position: 'absolute',
            right: 0,
            top: '50%',
            transform: 'translateY(-50%)',
          }}
        >✕</span>
      )}
    </div>
  );
};

return (
  <div ref={containerRef} className="table-wrapper" style={{ height: ui?.height ? `${ui.height}px` : '400px', overflow: 'auto' }}>
    <table className="table-root" lang="ru">
      <colgroup>
        {finalWidths.map((w, i) => <col key={i} style={{ width: `${w}px` }} />)}
      </colgroup>
      <thead
  className="table-header"
  ref={theadRef}
  style={{
    position: 'sticky',   // закрепляем весь thead
    top: 0,
    zIndex: 3,
    backgroundColor: '#F2F9FF',
  }}
>
  {allHeaderRows.map((row, rowIndex) => (
    <tr key={rowIndex}>
      {row.map((cell, cellIndex) => {
        if (cell.isColumn) {
          const colIndex = getColumnIndex(cell.column);
          return renderColumnHeader(cell.column, colIndex, true, cell.rowspan);
        } else if (cell.isGroup) {
          return (
            <th
              key={cellIndex}
              colSpan={cell.colspan}
              rowSpan={cell.rowspan}
              style={{
                textAlign: 'center',
                backgroundColor: '#e9edf2',
                border: '1px solid #d0d5dd',
                padding: '5px 2px',
                borderBottom: '1px solid #d0d5dd',
                // Убираем position: sticky, top, zIndex – теперь закрепляется весь thead
              }}
            >
              {cell.name || ''}
            </th>
          );
        }
        return <th key={cellIndex} style={{ display: 'none' }} />;
      })}
    </tr>
  ))}
</thead>
      <tbody>
        {data.map((row, rowIndex) => {
          const isReadonlyRow = row.is_editable === false;
          return (
            <tr key={row.row_id} className={isReadonlyRow ? 'table-row--readonly' : ''}
              style={{
                backgroundColor: row.row_background_color || undefined,
                color: row.row_text_color || undefined,
                ...(isReadonlyRow ? { position: 'sticky', top: `${headerHeight}px`, zIndex: 1 } : {}),
                ...(row.row_height > 0 ? { height: `${row.row_height}px` } : { height: '28px' }),
              }}>
              {visibleColumns.map((col, colIndex) => {
                // --- Row span (горизонтальное объединение) ---
                const rowSpanDef = rowSpans.find(s => s.row === rowIndex && colIndex >= s.start && colIndex <= s.end);
                if (rowSpanDef) {
                  if (colIndex !== rowSpanDef.start) return null;
                  const colSpan = rowSpanDef.end - rowSpanDef.start + 1;
                  const firstColIndex = rowSpanDef.start;
                  const effectiveCol = getCellMeta(rowIndex, firstColIndex) || visibleColumns[firstColIndex];
                  if (!effectiveCol) return null;
                  const columnName = `column${effectiveCol.column_order}`;
                  const cellValue = row[columnName] || '';
                  const isSumColumn = effectiveCol.column_data_type?.startsWith('sum_column');
                  const isSumRow = effectiveCol.column_data_type?.startsWith('sum_row');
                  const isComputed = isSumColumn || isSumRow;
                  let computedValue = cellValue;
                  if (isSumColumn) {
                    const rowIndices = parseIndexList(effectiveCol.metadata_description || '');
                    const rowsToSum = rowIndices.length > 0 ? rowIndices : data.map((_, idx) => idx);
                    computedValue = rowsToSum.reduce((sum, idx) => sum + (parseFloat(data[idx]?.[columnName]) || 0), 0);
                  } else if (isSumRow) {
                    const colIndices = parseIndexList(effectiveCol.metadata_description || '');
                    const colsToSum = colIndices.length > 0 ? colIndices : visibleColumns.map((_, idx) => idx);
                    computedValue = colsToSum.reduce((sum, idx) => sum + (parseFloat(row[`column${visibleColumns[idx]?.column_order}`]) || 0), 0);
                  }
                  const isEditable = hasEditPermission && effectiveCol.column_is_editable !== false && !isReadonlyRow && !isComputed;
                  const isEditingCell = editingCell && editingCell.rowId === row.row_id && editingCell.columnName === columnName;

                  return (
                    <td key={effectiveCol.column_order} colSpan={colSpan}
                      data-rowid={row.row_id} data-col={columnName}
                      className={!effectiveCol.column_is_editable ? 'table-col--readonly' : ''}
                      onClick={() => { if (isEditable) onCellActivate(row.row_id, columnName); }}
                      style={{
                        textAlign: 'center',
                        verticalAlign: 'middle',
                        backgroundColor: isEditingCell ? '#f0f7ff' : effectiveCol.column_background_color || col.column_background_color || undefined,
                        color: effectiveCol.column_text_color || col.column_text_color || undefined,
                        width: finalWidths[firstColIndex] ? `${finalWidths[firstColIndex]}px` : undefined,
                        minWidth: finalWidths[firstColIndex] ? `${finalWidths[firstColIndex]}px` : undefined,
                        maxWidth: finalWidths[firstColIndex] ? `${finalWidths[firstColIndex]}px` : undefined,
                        cursor: isEditable ? (effectiveCol.column_data_type?.startsWith('dropdown') || effectiveCol.column_data_type?.startsWith('datepicker') ? 'pointer' : 'text') : 'default',
                        ...getStickyStyle(firstColIndex, isReadonlyRow),
                      }}>
                      {renderCellContent({
                        effectiveCol,
                        cellValue,
                        isEditable,
                        isEditingCell,
                        isComputed,
                        computedValue,
                        columnName,
                        colIndex: firstColIndex,
                        rowId: row.row_id,
                        isUserAdded: row.is_user_added,
                        isReadonlyRow,
                      })}
                      {validationErrors[`${row.row_id}_${columnName}`] && editingCell?.inputElement && (
												(() => {
														try {
																if (!document.body.contains(editingCell.inputElement)) return null;
																const rect = editingCell.inputElement.getBoundingClientRect();
																const spaceBelow = window.innerHeight - rect.bottom;
																const tooltipHeight = 40;
																const showBelow = spaceBelow >= tooltipHeight + 4;
																return <TooltipPortal targetRect={rect} message={validationErrors[`${row.row_id}_${columnName}`]} showBelow={showBelow} />;
														} catch (e) { return null; }
												})()
										)}
                    </td>
                  );
                }

                // --- Column span (вертикальное объединение) ---
                const colSpanDef = colSpans.find(s => s.col === colIndex && rowIndex >= s.start && rowIndex <= s.end);
								if (colSpanDef) {
									if (rowIndex !== colSpanDef.start) return null;
									const rowSpan = colSpanDef.end - colSpanDef.start + 1;
									const effectiveCol = getCellMeta(colSpanDef.start, colIndex) || col;
									if (!effectiveCol) return null;
									const columnName = `column${effectiveCol.column_order}`;
									const firstRowOfSpan = data[colSpanDef.start];
									const cellValue = firstRowOfSpan ? (firstRowOfSpan[columnName] || '') : '';

									// ДОБАВЛЯЕМ ВЫЧИСЛЕНИЯ ДЛЯ СУММ (как в других ячейках)
									const isSumColumn = effectiveCol.column_data_type?.startsWith('sum_column');
									const isSumRow = effectiveCol.column_data_type?.startsWith('sum_row');
									const isComputed = isSumColumn || isSumRow;
									let computedValue = cellValue;
									if (isSumColumn) {
										const rowIndices = parseIndexList(effectiveCol.metadata_description || '');
										const rowsToSum = rowIndices.length > 0 ? rowIndices : data.map((_, idx) => idx);
										computedValue = rowsToSum.reduce((sum, idx) => sum + (parseFloat(data[idx]?.[columnName]) || 0), 0);
									} else if (isSumRow) {
										const colIndices = parseIndexList(effectiveCol.metadata_description || '');
										const colsToSum = colIndices.length > 0 ? colIndices : visibleColumns.map((_, idx) => idx);
										computedValue = colsToSum.reduce((sum, idx) => sum + (parseFloat(firstRowOfSpan?.[`column${visibleColumns[idx]?.column_order}`]) || 0), 0);
									}

									const startRowId = data[colSpanDef.start]?.row_id;
									const isStartRowReadonly = data[colSpanDef.start]?.is_editable === false;
									const isEditable = hasEditPermission && effectiveCol.column_is_editable !== false && !isStartRowReadonly && !isComputed;
									const isEditingCell = editingCell && editingCell.rowId === startRowId && editingCell.columnName === columnName;

                  return (
                    <td key={effectiveCol.column_order} rowSpan={rowSpan}
                      data-rowid={startRowId} data-col={columnName}
                      className={!effectiveCol.column_is_editable ? 'table-col--readonly' : ''}
                      onClick={() => { if (isEditable && startRowId) onCellActivate(startRowId, columnName); }}
                      style={{
                        textAlign: 'center',
                        verticalAlign: 'middle',
                        backgroundColor: isEditingCell ? '#f0f7ff' : effectiveCol.column_background_color || col.column_background_color || undefined,
                        color: effectiveCol.column_text_color || col.column_text_color || undefined,
                        width: finalWidths[colIndex] ? `${finalWidths[colIndex]}px` : undefined,
                        minWidth: finalWidths[colIndex] ? `${finalWidths[colIndex]}px` : undefined,
                        maxWidth: finalWidths[colIndex] ? `${finalWidths[colIndex]}px` : undefined,
                        cursor: isEditable ? (effectiveCol.column_data_type?.startsWith('dropdown') || effectiveCol.column_data_type?.startsWith('datepicker') ? 'pointer' : 'text') : 'default',
                        ...getStickyStyle(colIndex, isStartRowReadonly),
                      }}>
                      {renderCellContent({
                        effectiveCol,
                        cellValue,
                        isEditable,
                        isEditingCell,
                        isComputed,
                        computedValue,
                        columnName,
                        colIndex,
                        rowId: startRowId,
                        isUserAdded: firstRowOfSpan?.is_user_added,
                        isReadonlyRow: isStartRowReadonly,
                      })}
                      {validationErrors[`${startRowId}_${columnName}`] && editingCell?.inputElement && (
													(() => {
															try {
																	if (!document.body.contains(editingCell.inputElement)) return null;
																	const rect = editingCell.inputElement.getBoundingClientRect();
																	const spaceBelow = window.innerHeight - rect.bottom;
																	const tooltipHeight = 40;
																	const showBelow = spaceBelow >= tooltipHeight + 4;
																	return <TooltipPortal targetRect={rect} message={validationErrors[`${startRowId}_${columnName}`]} showBelow={showBelow} />;
															} catch (e) { return null; }
													})()
											)}
                    </td>
                  );
                }

                // --- Обычная ячейка ---
                const effectiveCol = getCellMeta(rowIndex, colIndex) || col;
                if (!effectiveCol) return <td key={col.column_order}></td>;
                const columnName = `column${effectiveCol.column_order}`;
                const cellValue = row[columnName] || '';
                const isSumColumn = effectiveCol.column_data_type?.startsWith('sum_column');
                const isSumRow = effectiveCol.column_data_type?.startsWith('sum_row');
                const isComputed = isSumColumn || isSumRow;
                let computedValue = cellValue;
                if (isSumColumn) {
                  const rowIndices = parseIndexList(effectiveCol.metadata_description || '');
                  const rowsToSum = rowIndices.length > 0 ? rowIndices : data.map((_, idx) => idx);
                  computedValue = rowsToSum.reduce((sum, idx) => sum + (parseFloat(data[idx]?.[columnName]) || 0), 0);
                } else if (isSumRow) {
                  const colIndices = parseIndexList(effectiveCol.metadata_description || '');
                  const colsToSum = colIndices.length > 0 ? colIndices : visibleColumns.map((_, idx) => idx);
                  computedValue = colsToSum.reduce((sum, idx) => sum + (parseFloat(row[`column${visibleColumns[idx]?.column_order}`]) || 0), 0);
                }
                const isEditable = hasEditPermission && effectiveCol.column_is_editable !== false && !isReadonlyRow && !isComputed;
                const isEditingCell = editingCell && editingCell.rowId === row.row_id && editingCell.columnName === columnName;

                return (
                  <td key={col.column_order}
                    data-rowid={row.row_id} data-col={columnName}
                    className={!effectiveCol.column_is_editable ? 'table-col--readonly' : ''}
                    onClick={() => { if (isEditable) onCellActivate(row.row_id, columnName); }}
                    style={{
                      width: `${finalWidths[colIndex]}px`,
                      backgroundColor: effectiveCol.column_background_color || col.column_background_color || '#fff',
                      color: effectiveCol.column_text_color || undefined,
                      cursor: isEditable ? (effectiveCol.column_data_type?.startsWith('dropdown') || effectiveCol.column_data_type?.startsWith('datepicker') ? 'pointer' : 'text') : 'default',
                      ...(isEditingCell && { backgroundColor: '#f0f7ff' }),
                      ...getStickyStyle(colIndex, isReadonlyRow),
                    }}>
                    {renderCellContent({
                      effectiveCol,
                      cellValue,
                      isEditable,
                      isEditingCell,
                      isComputed,
                      computedValue,
                      columnName,
                      colIndex,
                      rowId: row.row_id,
                      isUserAdded: row.is_user_added,
                      isReadonlyRow,
                    })}
                    {validationErrors[`${row.row_id}_${columnName}`] && editingCell?.inputElement && (
							(() => {
								try {
									if (!document.body.contains(editingCell.inputElement)) return null
									const rect = editingCell.inputElement.getBoundingClientRect();
									const spaceBelow = window.innerHeight - rect.bottom;
									const tooltipHeight = 40;
									const showBelow = spaceBelow >= tooltipHeight + 4;
									return (
										<TooltipPortal
											targetRect={rect}
											message={validationErrors[`${row.row_id}_${columnName}`]}
											showBelow={showBelow} 
										/>
									);
								} catch (e) {
									return null
								}

							})()
							)}
                  </td>
                );
              })}
            </tr>
          );
        })}
        {canAddRow && (
          <tr onClick={handleAddRow} style={{ cursor: 'pointer' }}>
            <td colSpan={visibleColumns.length} style={{ textAlign: 'start', padding: '6px', backgroundColor: '#F2F9FF', border: '1px dashed #ccc', color: '#666', fontStyle: 'italic' }}>
              + Добавить строку
            </td>
          </tr>
        )}
      </tbody>
    </table>
	<div id="portal"></div>  
	{hoveredHeader && (
  <TooltipPortal
    targetRect={hoveredHeader.targetRect}
    message={hoveredHeader.message}
    showBelow={true}   // можно вычислить как для ячеек
    type="info"
  />
)}
	{dropdownTarget && (
		<DropdownMenu
			options={dropdownConfig[dropdownTarget.columnName] || []}
			value={localEditValue}
			onSelect={(val) => {
				commitEdit(val);
				setDropdownTarget(null);
			}}
			onClose={() => {
				setDropdownTarget(null);
				setEditingCell(null);
			}}
			targetRect={dropdownTarget.rect}
		/>
	)}
	{datePickerTarget && (
		<DatePickerMenu
			value={localEditValue}
			onSelect={(val) => {
				commitEdit(val);
				setDatePickerTarget(null);
			}}
			onClose={() => {
				setDatePickerTarget(null);
				setEditingCell(null);
			}}
			targetRect={datePickerTarget.rect}
		/>
	)}
	</div>
	)
}

function AppWrapper() {
    const [tabKey, setTabKey] = React.useState(0);

    React.useEffect(() => {
        appsmith.onModelChange((model) => {
            const newKey = model._tabKey ?? 0;
            console.log('AppWrapper: new tabKey =', newKey);
            setTabKey(newKey);
        });
    }, []);

    console.log('AppWrapper render, tabKey =', tabKey);
    return <App key={tabKey} />;
}

appsmith.onReady(() => {
    reactDom.render(<AppWrapper />, document.getElementById("root"));
});
